/* ============================================================================
   data.js — demo dataset for the NovaCart admin console.

   FRONTEND ONLY. Nothing here talks to a server. Every record is a literal
   object so the shapes are obvious and greppable.

   Replacing this with Laravel data
   --------------------------------
   Each top-level key maps to one query or repository call:

     DB.categories  ->  Category::withCount('products')->orderBy('sort_order')->get()
     DB.brands      ->  Brand::withCount('products')->get()
     DB.products    ->  Product::with('category','brand')->paginate(20)
     DB.orders      ->  Order::with('customer','items')->latest()->paginate(20)
     DB.customers   ->  Customer::withCount('orders')->withSum('orders','total')->paginate(20)
     DB.reviews     ->  Review::with('product','customer')->latest()->paginate(20)
     DB.coupons     ->  Coupon::orderByDesc('created_at')->paginate(20)
     DB.inventory   ->  StockLevel::with('product')->get()
     DB.payments    ->  Payment::with('order.customer')->latest()->paginate(20)
     DB.staff       ->  User::where('role','!=','customer')->paginate(20)
     DB.notifications / DB.activity -> Notification:: / ActivityLog::latest()
     DB.kpis / DB.analytics -> aggregate queries (SUM/COUNT/GROUP BY), not rows

   `orders`, `customers` and `products` are representative samples (what one
   page of a paginated table returns). `kpis` and `analytics` are store-wide
   aggregates. Keep those two concerns separate server-side too.

   Image paths are relative to the project root; resolve them with
   `DB.url(path)`, which prefixes the current page's asset base.

   Generated by build/gen-data.mjs — deterministic, safe to re-run.
   ========================================================================== */

